-- Etapas 18.68/18.69. REVIEW DRAFT ONLY: NOT EXECUTED.
-- Source: Downloads/Supabase Snippet Untitled query (1).csv, seven full
-- pg_get_functiondef exports, read as UTF-8 and compared with main.py.
-- No existing function, table privilege, trigger or business rule is changed.
-- No Auth Admin operations, collective signatures or assignments are added.
-- Backend integration is a separate step: actor comes from the verified JWT,
-- never from the HTTP body; request_id is generated by the backend.
-- request_id is correlation, NOT an idempotency guarantee. Do not blindly retry.
-- Old RPCs/direct DML remain available: this is NOT full audit enforcement yet.

BEGIN;

DO $preflight$
DECLARE
  expected record;
  function_oid oid;
BEGIN
  IF current_user <> 'postgres' THEN
    RAISE EXCEPTION 'Audited RPC migration requires current_user = postgres';
  END IF;
  IF to_regclass('public.activity_logs') IS NULL
     OR to_regnamespace('private') IS NULL THEN
    RAISE EXCEPTION 'Apply the reviewed activity_logs migration first';
  END IF;
  IF (SELECT nspowner FROM pg_namespace WHERE nspname = 'private')
     <> (SELECT oid FROM pg_roles WHERE rolname = 'postgres') THEN
    RAISE EXCEPTION 'Review private schema ownership before continuing';
  END IF;
  IF has_schema_privilege('anon', 'private', 'CREATE')
     OR has_schema_privilege('authenticated', 'private', 'CREATE')
     OR has_schema_privilege('service_role', 'private', 'CREATE') THEN
    RAISE EXCEPTION 'Application roles must not have CREATE on private';
  END IF;

  -- Abort on source drift. Hashes are of the exact exported definitions,
  -- including line endings. A formatting-only mismatch also needs review.
  FOR expected IN SELECT * FROM (VALUES
    ('public.create_order_with_customer_and_stock(text,text,text,text,text,numeric,jsonb,text)', '3ff2ac2bb293fe5c2d31131d703762dc'),
    ('public.create_order_with_stock(text,text,text,text,text,numeric,jsonb)', '020b31a9d53cd21a65b34a18385f36ee'),
    ('public.create_product_with_stock(text,text,integer,integer,integer,numeric,boolean)', 'ca1ed8e591c040e6e02791253f5c7ea0'),
    ('public.move_product_stock(text,integer)', '0b5734a57890d82f4e0894dc1af3dd73'),
    ('public.transition_order_separation(text,text)', '0a7fc0556427885e077ea81927c7c264'),
    ('public.update_order_with_customer_and_stock(text,text,text,text,text,numeric,jsonb,text)', 'c3fc9f8af99bcb7dcf54d2c917c85c41'),
    ('public.update_order_with_stock(text,text,text,text,text,numeric,jsonb)', '1a68af23bde506d44b5038eccaab821d')
  ) AS source(signature, definition_md5)
  LOOP
    function_oid := to_regprocedure(expected.signature);
    IF function_oid IS NULL THEN
      RAISE EXCEPTION 'Missing original RPC: %', expected.signature;
    END IF;
    IF md5(pg_get_functiondef(function_oid)) <> expected.definition_md5 THEN
      RAISE EXCEPTION 'Original RPC differs from reviewed CSV: %', expected.signature;
    END IF;
    IF EXISTS (SELECT 1 FROM pg_proc p WHERE p.oid = function_oid
               AND (p.prosecdef OR pg_get_userbyid(p.proowner) <> 'postgres')) THEN
      RAISE EXCEPTION 'Unexpected original RPC security context: %', expected.signature;
    END IF;
  END LOOP;
END;
$preflight$;

-- Helpers are INVOKER: only postgres-owned audited entry points may call them.
-- Lock the actor to keep status/role stable until the transaction finishes.
-- This serializes simultaneous audited operations by the same actor.
CREATE FUNCTION private.activity_require_actor(
  p_actor_id uuid, p_request_id uuid, p_admin_only boolean
) RETURNS text
LANGUAGE plpgsql SECURITY INVOKER SET search_path = ''
AS $function$
DECLARE
  actor public.profiles%ROWTYPE;
BEGIN
  IF p_actor_id IS NULL OR p_request_id IS NULL OR p_admin_only IS NULL THEN
    RAISE EXCEPTION 'Actor and request_id are required' USING ERRCODE = '22023';
  END IF;
  SELECT p.* INTO actor FROM public.profiles p
    WHERE p.id = p_actor_id FOR NO KEY UPDATE;
  IF NOT FOUND OR actor.status IS DISTINCT FROM 'active'
     OR actor.role IS NULL OR actor.role NOT IN ('admin', 'employee') THEN
    RAISE EXCEPTION 'Perfil não autorizado.' USING ERRCODE = '42501';
  END IF;
  IF p_admin_only AND actor.role <> 'admin' THEN
    RAISE EXCEPTION 'Esta operação exige um administrador.' USING ERRCODE = '42501';
  END IF;
  RETURN actor.role;
END;
$function$;

-- Validate permitted scalar fields, including historical null values.
CREATE FUNCTION private.activity_validate_fields(p_values jsonb, p_allowed text[])
RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = ''
AS $function$
DECLARE
  field record;
  value_type text;
BEGIN
  IF jsonb_typeof(p_values) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Audit fields must be an object' USING ERRCODE = '22023';
  END IF;
  FOR field IN SELECT key, value FROM jsonb_each(p_values)
  LOOP
    IF NOT (field.key = ANY(p_allowed)) THEN
      RAISE EXCEPTION 'Unexpected audit field: %', field.key USING ERRCODE = '22023';
    END IF;
    value_type := jsonb_typeof(field.value);
    IF value_type = 'null' THEN CONTINUE; END IF;
    IF field.key IN ('quantity', 'initial_quantity', 'min', 'max', 'item_count',
                     'delta', 'previous_quantity', 'new_quantity') THEN
      IF value_type <> 'number' THEN
        RAISE EXCEPTION 'Audit quantity must be numeric' USING ERRCODE = '22023';
      END IF;
      IF (field.value #>> '{}')::numeric <> trunc((field.value #>> '{}')::numeric) THEN
        RAISE EXCEPTION 'Audit quantity must be integral' USING ERRCODE = '22023';
      END IF;
    ELSIF field.key IN ('active', 'stock_applied') THEN
      IF value_type <> 'boolean' THEN
        RAISE EXCEPTION 'Audit flag must be boolean' USING ERRCODE = '22023';
      END IF;
    ELSIF field.key IN ('total', 'unit_price') THEN
      IF value_type <> 'string'
         OR (field.value #>> '{}') !~ '^-?[0-9]+([.][0-9]+)?$' THEN
        RAISE EXCEPTION 'Audit money must be a decimal string' USING ERRCODE = '22023';
      END IF;
    ELSIF value_type <> 'string' THEN
      RAISE EXCEPTION 'Audit text field must be a string' USING ERRCODE = '22023';
    END IF;
  END LOOP;
END;
$function$;

CREATE FUNCTION private.activity_changes(p_before jsonb, p_after jsonb)
RETURNS jsonb LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path = ''
AS $function$
  SELECT COALESCE(jsonb_object_agg(a.key, jsonb_build_object(
    'before', p_before -> a.key, 'after', a.value)), '{}'::jsonb)
  FROM jsonb_each(p_after) a
  WHERE (p_before -> a.key) IS DISTINCT FROM a.value;
$function$;

-- Explicit allowlist; no row IDs/timestamps or unreviewed columns are copied.
-- Numeric prices are normalized to decimal strings without insignificant zeros.
-- Sorted JSON arrays preserve duplicates (multiset comparison, not item identity).
CREATE FUNCTION private.activity_order_snapshot(p_order_id text)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path = ''
AS $function$
  SELECT jsonb_build_object(
    'supplier', o.supplier, 'customer', o.customer,
    'operation', o.operation, 'status', o.status,
    'date', o.order_date,
    'total', trim_scale(o.total::numeric)::text,
    'stock_applied', o.stock_applied,
    'items', COALESCE((
      SELECT jsonb_agg(i.item ORDER BY i.item::text COLLATE "C")
      FROM (
        SELECT jsonb_build_object(
          'product_id', oi.product_id, 'product', oi.product,
          'quantity', oi.quantity,
          'unit_price', trim_scale(oi.unit_price::numeric)::text
        ) AS item
        FROM public.order_items oi WHERE oi.order_id = o.id
      ) i
    ), '[]'::jsonb)
  ) FROM public.orders o WHERE o.id = p_order_id;
$function$;

CREATE FUNCTION private.activity_item_changes(p_before jsonb, p_after jsonb)
RETURNS jsonb LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path = ''
AS $function$
  SELECT COALESCE(jsonb_agg(x.event ORDER BY x.event::text COLLATE "C"), '[]'::jsonb)
  FROM (
    SELECT jsonb_build_object('kind', 'removed', 'item', r.value) AS event
    FROM (
      SELECT value FROM jsonb_array_elements(p_before)
      EXCEPT ALL
      SELECT value FROM jsonb_array_elements(p_after)
    ) r
    UNION ALL
    SELECT jsonb_build_object('kind', 'added', 'item', a.value)
    FROM (
      SELECT value FROM jsonb_array_elements(p_after)
      EXCEPT ALL
      SELECT value FROM jsonb_array_elements(p_before)
    ) a
  ) x;
$function$;

-- Private insertion only. No caller-controlled actor_role, timestamp or id.
-- This phase intentionally supports only database events, not Auth Admin events.
CREATE FUNCTION private.activity_write(
  p_actor_id uuid, p_request_id uuid, p_action text,
  p_entity_type text, p_entity_id text, p_details jsonb
) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = ''
AS $function$
DECLARE
  actor_role text;
  expected_entity text;
  detail_keys text[];
  change_keys text[];
  change record;
  event jsonb;
  payload jsonb;
BEGIN
  actor_role := private.activity_require_actor(p_actor_id, p_request_id,
    p_action NOT IN ('order.separation_started', 'order.separation_completed', 'profile.name_updated'));
  CASE p_action
    WHEN 'order.created', 'order.deleted' THEN
      expected_entity := 'order';
      detail_keys := ARRAY['schema_version', 'operation', 'status', 'item_count', 'total'];
    WHEN 'order.updated' THEN
      expected_entity := 'order';
      detail_keys := ARRAY['schema_version', 'changes', 'item_changes'];
      -- Status/stock_applied are logged because ORIGINAL edit RPCs change them.
      -- Their existing status behavior is deliberately not redesigned here.
      change_keys := ARRAY['supplier', 'customer', 'operation', 'status', 'date', 'total', 'stock_applied'];
    WHEN 'order.separation_started', 'order.separation_completed' THEN
      expected_entity := 'order';
      detail_keys := ARRAY['schema_version', 'previous_status', 'new_status'];
    WHEN 'product.created' THEN
      expected_entity := 'product';
      detail_keys := ARRAY['schema_version', 'name', 'initial_quantity', 'min', 'max', 'unit_price', 'active'];
    WHEN 'product.updated' THEN
      expected_entity := 'product';
      detail_keys := ARRAY['schema_version', 'changes'];
      change_keys := ARRAY['name', 'min', 'max', 'unit_price', 'active'];
    WHEN 'product.deleted' THEN
      expected_entity := 'product';
      detail_keys := ARRAY['schema_version', 'name', 'quantity', 'active'];
    WHEN 'stock.adjusted' THEN
      expected_entity := 'product';
      detail_keys := ARRAY['schema_version', 'delta', 'previous_quantity', 'new_quantity'];
    WHEN 'profile.name_updated' THEN
      expected_entity := 'profile';
      detail_keys := ARRAY['schema_version', 'changes'];
      change_keys := ARRAY['name'];
      IF p_entity_id IS DISTINCT FROM p_actor_id::text THEN
        RAISE EXCEPTION 'Only the own profile name may be changed' USING ERRCODE = '42501';
      END IF;
    WHEN 'employee.status_updated' THEN
      expected_entity := 'profile';
      detail_keys := ARRAY['schema_version', 'changes'];
      change_keys := ARRAY['status'];
    ELSE
      RAISE EXCEPTION 'Unsupported audit action' USING ERRCODE = '22023';
  END CASE;
  IF p_entity_type IS DISTINCT FROM expected_entity
     OR p_entity_id IS NULL OR btrim(p_entity_id) = '' THEN
    RAISE EXCEPTION 'Invalid audit entity' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_details) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Audit details must be an object' USING ERRCODE = '22023';
  END IF;
  IF (p_details -> 'schema_version') IS DISTINCT FROM '1'::jsonb
     OR NOT (p_details ?& detail_keys)
     OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_details) k(key)
                WHERE NOT (k.key = ANY(detail_keys))) THEN
    RAISE EXCEPTION 'Unexpected or missing audit details' USING ERRCODE = '22023';
  END IF;

  IF change_keys IS NOT NULL THEN
    IF jsonb_typeof(p_details -> 'changes') IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'Audit changes must be an object' USING ERRCODE = '22023';
    END IF;
    FOR change IN SELECT key, value FROM jsonb_each(p_details -> 'changes')
    LOOP
      IF NOT (change.key = ANY(change_keys))
         OR jsonb_typeof(change.value) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'Invalid audit change' USING ERRCODE = '22023';
      END IF;
      IF NOT (change.value ?& ARRAY['before', 'after'])
         OR (change.value - ARRAY['before', 'after']) <> '{}'::jsonb
         OR (change.value -> 'before') IS NOT DISTINCT FROM (change.value -> 'after') THEN
        RAISE EXCEPTION 'Invalid or ineffective before/after change' USING ERRCODE = '22023';
      END IF;
      PERFORM private.activity_validate_fields(
        jsonb_build_object(change.key, change.value -> 'before'), change_keys);
      PERFORM private.activity_validate_fields(
        jsonb_build_object(change.key, change.value -> 'after'), change_keys);
    END LOOP;
    IF p_action = 'order.updated' THEN
      IF jsonb_typeof(p_details -> 'item_changes') IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'item_changes must be an array' USING ERRCODE = '22023';
      END IF;
      FOR event IN SELECT value FROM jsonb_array_elements(p_details -> 'item_changes')
      LOOP
        IF jsonb_typeof(event) IS DISTINCT FROM 'object' THEN
          RAISE EXCEPTION 'Invalid item event' USING ERRCODE = '22023';
        END IF;
        IF NOT (event ?& ARRAY['kind', 'item'])
           OR (event - ARRAY['kind', 'item']) <> '{}'::jsonb
           OR (event ->> 'kind') IS NULL
           OR (event ->> 'kind') NOT IN ('added', 'removed') THEN
          RAISE EXCEPTION 'Invalid item event fields' USING ERRCODE = '22023';
        END IF;
        PERFORM private.activity_validate_fields(event -> 'item',
          ARRAY['product_id', 'product', 'quantity', 'unit_price']);
        IF NOT ((event -> 'item') ?& ARRAY['product_id', 'product', 'quantity', 'unit_price']) THEN
          RAISE EXCEPTION 'Incomplete item event' USING ERRCODE = '22023';
        END IF;
      END LOOP;
      IF p_details -> 'changes' = '{}'::jsonb AND p_details -> 'item_changes' = '[]'::jsonb THEN
        RAISE EXCEPTION 'Empty order change' USING ERRCODE = '22023';
      END IF;
    ELSIF p_details -> 'changes' = '{}'::jsonb THEN
      RAISE EXCEPTION 'Empty change' USING ERRCODE = '22023';
    END IF;
  ELSE
    payload := p_details - 'schema_version';
    PERFORM private.activity_validate_fields(payload, detail_keys);
  END IF;
  IF p_action IN ('order.separation_started', 'order.separation_completed') THEN
    IF (p_action = 'order.separation_started' AND
        ((p_details ->> 'previous_status') IS DISTINCT FROM 'waiting'
         OR (p_details ->> 'new_status') IS DISTINCT FROM 'separating'))
       OR (p_action = 'order.separation_completed' AND
        ((p_details ->> 'previous_status') IS DISTINCT FROM 'separating'
         OR (p_details ->> 'new_status') IS DISTINCT FROM 'completed')) THEN
      RAISE EXCEPTION 'Invalid separation audit transition' USING ERRCODE = '22023';
    END IF;
  END IF;
  IF p_action = 'stock.adjusted' THEN
    IF (p_details ->> 'delta') IS NULL
       OR (p_details ->> 'previous_quantity') IS NULL
       OR (p_details ->> 'new_quantity') IS NULL THEN
      RAISE EXCEPTION 'Missing stock quantities' USING ERRCODE = '22023';
    END IF;
    IF (p_details ->> 'delta')::numeric = 0
       OR (p_details ->> 'previous_quantity')::numeric < 0
       OR (p_details ->> 'new_quantity')::numeric < 0
       OR (p_details ->> 'previous_quantity')::numeric + (p_details ->> 'delta')::numeric
          <> (p_details ->> 'new_quantity')::numeric THEN
      RAISE EXCEPTION 'Inconsistent stock audit' USING ERRCODE = '22023';
    END IF;
  END IF;
  INSERT INTO public.activity_logs (
    actor_id, actor_role, action, entity_type, entity_id, request_id, details
  ) VALUES (
    p_actor_id, actor_role, p_action, p_entity_type, p_entity_id, p_request_id, p_details
  );
END;
$function$;

-- Wrappers delegate to the reviewed originals; exceptions propagate unchanged.
CREATE FUNCTION public.audit_create_order(
  p_actor_id uuid, p_request_id uuid,
  p_order_id text, p_supplier text, p_operation text, p_status text,
  p_order_date text, p_total numeric, p_items jsonb, p_customer text
) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $function$
DECLARE
  snapshot jsonb;
BEGIN
  PERFORM private.activity_require_actor(p_actor_id, p_request_id, true);
  PERFORM public.create_order_with_customer_and_stock(
    p_order_id, p_supplier, p_operation, p_status, p_order_date, p_total, p_items, p_customer);
  snapshot := private.activity_order_snapshot(p_order_id);
  IF snapshot IS NULL THEN RAISE EXCEPTION 'Created order was not found'; END IF;
  PERFORM private.activity_write(p_actor_id, p_request_id, 'order.created', 'order', p_order_id,
    jsonb_build_object('schema_version', 1, 'operation', snapshot -> 'operation',
      'status', snapshot -> 'status', 'item_count', jsonb_array_length(snapshot -> 'items'),
      'total', snapshot -> 'total'));
END;
$function$;

CREATE FUNCTION public.audit_update_order(
  p_actor_id uuid, p_request_id uuid,
  p_order_id text, p_supplier text, p_operation text, p_status text,
  p_order_date text, p_total numeric, p_items jsonb, p_customer text
) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $function$
DECLARE
  before_snapshot jsonb;
  after_snapshot jsonb;
  changes jsonb;
  item_changes jsonb;
  previous_status text;
BEGIN
  PERFORM private.activity_require_actor(p_actor_id, p_request_id, true);
  SELECT o.status INTO previous_status FROM public.orders o
    WHERE o.id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pedido não encontrado.'; END IF;
  -- Existing HTTP prohibition, made atomic; no new allowed-status policy.
  -- Backend integration must map this message to its existing HTTP 409.
  IF previous_status = 'completed' THEN
    RAISE EXCEPTION 'Pedidos concluídos não podem ser editados.';
  END IF;
  before_snapshot := private.activity_order_snapshot(p_order_id);
  PERFORM public.update_order_with_customer_and_stock(
    p_order_id, p_supplier, p_operation, p_status, p_order_date, p_total, p_items, p_customer);
  after_snapshot := private.activity_order_snapshot(p_order_id);
  IF after_snapshot IS NULL THEN RAISE EXCEPTION 'Updated order was not found'; END IF;
  changes := private.activity_changes(before_snapshot - 'items', after_snapshot - 'items');
  item_changes := private.activity_item_changes(before_snapshot -> 'items', after_snapshot -> 'items');
  IF changes <> '{}'::jsonb OR item_changes <> '[]'::jsonb THEN
    PERFORM private.activity_write(p_actor_id, p_request_id, 'order.updated', 'order', p_order_id,
      jsonb_build_object('schema_version', 1, 'changes', changes, 'item_changes', item_changes));
  END IF;
END;
$function$;

CREATE FUNCTION public.audit_delete_order(p_actor_id uuid, p_request_id uuid, p_order_id text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $function$
DECLARE
  snapshot jsonb;
BEGIN
  PERFORM private.activity_require_actor(p_actor_id, p_request_id, true);
  PERFORM 1 FROM public.orders o WHERE o.id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pedido não encontrado.' USING ERRCODE = 'P0002'; END IF;
  snapshot := private.activity_order_snapshot(p_order_id);
  -- Preserve current deletion semantics/FKs. No invented stock reversal.
  DELETE FROM public.orders o WHERE o.id = p_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order deletion was not applied'; END IF;
  PERFORM private.activity_write(p_actor_id, p_request_id, 'order.deleted', 'order', p_order_id,
    jsonb_build_object('schema_version', 1, 'operation', snapshot -> 'operation',
      'status', snapshot -> 'status', 'item_count', jsonb_array_length(snapshot -> 'items'),
      'total', snapshot -> 'total'));
END;
$function$;

CREATE FUNCTION public.audit_create_product(
  p_actor_id uuid, p_request_id uuid, p_id text, p_name text,
  p_quantity integer, p_min integer, p_max integer, p_unit_price numeric, p_active boolean
) RETURNS SETOF public.products
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $function$
DECLARE
  saved public.products%ROWTYPE;
BEGIN
  PERFORM private.activity_require_actor(p_actor_id, p_request_id, true);
  SELECT p.* INTO STRICT saved FROM public.create_product_with_stock(
    p_id, p_name, p_quantity, p_min, p_max, p_unit_price, p_active) p;
  PERFORM private.activity_write(p_actor_id, p_request_id, 'product.created', 'product', saved.id,
    jsonb_build_object('schema_version', 1, 'name', saved.name,
      'initial_quantity', saved.quantity, 'min', saved.min, 'max', saved.max,
      'unit_price', trim_scale(saved.unit_price::numeric)::text, 'active', saved.active));
  RETURN NEXT saved;
END;
$function$;

CREATE FUNCTION public.audit_update_product(
  p_actor_id uuid, p_request_id uuid, p_id text, p_name text,
  p_min integer, p_max integer, p_unit_price numeric, p_active boolean
) RETURNS SETOF public.products
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $function$
DECLARE
  previous public.products%ROWTYPE;
  saved public.products%ROWTYPE;
  before_fields jsonb;
  after_fields jsonb;
  changes jsonb;
BEGIN
  PERFORM private.activity_require_actor(p_actor_id, p_request_id, true);
  IF p_name IS NULL OR p_min IS NULL OR p_max IS NULL OR p_unit_price IS NULL OR p_active IS NULL
     OR p_min < 0 OR p_max < 1 OR p_min > p_max OR p_unit_price < 0 THEN
    RAISE EXCEPTION 'Quantidade, limites ou preço inválidos.' USING ERRCODE = '22023';
  END IF;
  SELECT p.* INTO previous FROM public.products p WHERE p.id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Produto não encontrado.' USING ERRCODE = 'P0002'; END IF;
  before_fields := jsonb_build_object('name', previous.name, 'min', previous.min,
    'max', previous.max, 'unit_price', trim_scale(previous.unit_price::numeric)::text, 'active', previous.active);
  UPDATE public.products p SET name = p_name, min = p_min, max = p_max,
    unit_price = p_unit_price, active = p_active
    WHERE p.id = p_id RETURNING p.* INTO saved;
  IF NOT FOUND THEN RAISE EXCEPTION 'Product update was not applied'; END IF;
  after_fields := jsonb_build_object('name', saved.name, 'min', saved.min,
    'max', saved.max, 'unit_price', trim_scale(saved.unit_price::numeric)::text, 'active', saved.active);
  changes := private.activity_changes(before_fields, after_fields);
  IF changes <> '{}'::jsonb THEN
    PERFORM private.activity_write(p_actor_id, p_request_id, 'product.updated', 'product', p_id,
      jsonb_build_object('schema_version', 1, 'changes', changes));
  END IF;
  RETURN NEXT saved;
END;
$function$;

CREATE FUNCTION public.audit_delete_product(p_actor_id uuid, p_request_id uuid, p_product_id text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $function$
DECLARE
  previous public.products%ROWTYPE;
BEGIN
  PERFORM private.activity_require_actor(p_actor_id, p_request_id, true);
  SELECT p.* INTO previous FROM public.products p WHERE p.id = p_product_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Produto não encontrado.' USING ERRCODE = 'P0002'; END IF;
  IF EXISTS (SELECT 1 FROM public.order_items oi WHERE oi.product_id = p_product_id) THEN
    RAISE EXCEPTION 'Não é possível excluir este produto, pois ele possui pedidos vinculados.'
      USING ERRCODE = '23503';
  END IF;
  DELETE FROM public.products p WHERE p.id = p_product_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Product deletion was not applied'; END IF;
  PERFORM private.activity_write(p_actor_id, p_request_id, 'product.deleted', 'product', p_product_id,
    jsonb_build_object('schema_version', 1, 'name', previous.name,
      'quantity', previous.quantity, 'active', previous.active));
END;
$function$;

CREATE FUNCTION public.audit_adjust_stock(
  p_actor_id uuid, p_request_id uuid, p_product_id text, p_delta integer
) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $function$
DECLARE
  previous_quantity integer;
  new_quantity integer;
BEGIN
  PERFORM private.activity_require_actor(p_actor_id, p_request_id, true);
  -- Preserve original zero/null-delta errors and integer return.
  IF p_delta IS NULL OR p_delta = 0 THEN
    RETURN public.move_product_stock(p_product_id, p_delta);
  END IF;
  SELECT p.quantity INTO previous_quantity FROM public.products p
    WHERE p.id = p_product_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Produto não encontrado.'; END IF;
  new_quantity := public.move_product_stock(p_product_id, p_delta);
  PERFORM private.activity_write(p_actor_id, p_request_id, 'stock.adjusted', 'product', p_product_id,
    jsonb_build_object('schema_version', 1, 'delta', p_delta,
      'previous_quantity', previous_quantity, 'new_quantity', new_quantity));
  RETURN new_quantity;
END;
$function$;

CREATE FUNCTION public.audit_transition_order_separation(
  p_actor_id uuid, p_request_id uuid, p_order_id text, p_action text
) RETURNS TABLE(order_id text, status text, changed boolean)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $function$
DECLARE
  result record;
BEGIN
  PERFORM private.activity_require_actor(p_actor_id, p_request_id, false);
  SELECT s.* INTO STRICT result
    FROM public.transition_order_separation(p_order_id, p_action) s;
  -- The original validates/locks and implements idempotent start/confirm.
  -- No catch-all exception handler: P2001..P2005 propagate unchanged.
  IF result.changed THEN
    PERFORM private.activity_write(p_actor_id, p_request_id,
      CASE p_action WHEN 'start' THEN 'order.separation_started' ELSE 'order.separation_completed' END,
      'order', result.order_id,
      jsonb_build_object('schema_version', 1,
        'previous_status', CASE p_action WHEN 'start' THEN 'waiting' ELSE 'separating' END,
        'new_status', result.status));
  END IF;
  RETURN QUERY SELECT result.order_id::text, result.status::text, result.changed::boolean;
END;
$function$;

CREATE FUNCTION public.audit_update_own_name(p_actor_id uuid, p_request_id uuid, p_name text)
RETURNS TABLE(id uuid, name text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $function$
DECLARE
  previous_name text;
  saved_name text;
  changes jsonb;
BEGIN
  PERFORM private.activity_require_actor(p_actor_id, p_request_id, false);
  IF p_name IS NULL OR char_length(btrim(p_name)) NOT BETWEEN 1 AND 120 THEN
    RAISE EXCEPTION 'Nome inválido.' USING ERRCODE = '22023';
  END IF;
  SELECT p.name INTO previous_name FROM public.profiles p
    WHERE p.id = p_actor_id AND p.status = 'active' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Perfil ativo não encontrado.' USING ERRCODE = '42501'; END IF;
  UPDATE public.profiles p SET name = btrim(p_name)
    WHERE p.id = p_actor_id AND p.status = 'active' RETURNING p.name INTO saved_name;
  IF NOT FOUND THEN RAISE EXCEPTION 'Profile update was not applied'; END IF;
  changes := private.activity_changes(jsonb_build_object('name', previous_name), jsonb_build_object('name', saved_name));
  IF changes <> '{}'::jsonb THEN
    PERFORM private.activity_write(p_actor_id, p_request_id, 'profile.name_updated', 'profile', p_actor_id::text,
      jsonb_build_object('schema_version', 1, 'changes', changes));
  END IF;
  RETURN QUERY SELECT p_actor_id, saved_name;
END;
$function$;

CREATE FUNCTION public.audit_update_employee_status(
  p_actor_id uuid, p_request_id uuid, p_user_id uuid, p_status text
) RETURNS TABLE(id uuid, name text, role text, status text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $function$
DECLARE
  previous public.profiles%ROWTYPE;
  saved public.profiles%ROWTYPE;
  changes jsonb;
BEGIN
  PERFORM private.activity_require_actor(p_actor_id, p_request_id, true);
  IF p_status IS NULL OR p_status NOT IN ('active', 'inactive') THEN
    RAISE EXCEPTION 'Status inválido.' USING ERRCODE = '22023';
  END IF;
  SELECT p.* INTO previous FROM public.profiles p WHERE p.id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Funcionário não encontrado.' USING ERRCODE = 'P0002'; END IF;
  IF previous.role IS DISTINCT FROM 'employee' THEN
    RAISE EXCEPTION 'Esta operação só é permitida para funcionários.' USING ERRCODE = '42501';
  END IF;
  IF previous.name IS NULL OR previous.name = '' THEN
    RAISE EXCEPTION 'Perfil de funcionário inconsistente';
  END IF;
  UPDATE public.profiles p SET status = p_status
    WHERE p.id = p_user_id RETURNING p.* INTO saved;
  IF NOT FOUND THEN RAISE EXCEPTION 'Employee update was not applied'; END IF;
  changes := private.activity_changes(jsonb_build_object('status', previous.status), jsonb_build_object('status', saved.status));
  IF changes <> '{}'::jsonb THEN
    PERFORM private.activity_write(p_actor_id, p_request_id, 'employee.status_updated', 'profile', p_user_id::text,
      jsonb_build_object('schema_version', 1, 'changes', changes));
  END IF;
  RETURN QUERY SELECT saved.id::uuid, saved.name::text, saved.role::text, saved.status::text;
END;
$function$;

-- Only NEW functions are affected. No schema-wide/default privilege changes.
-- No GRANT on private schema, tables or sequences is needed for service_role.
-- The trusted owner executes all helpers inside the protected transaction.
DO $permissions$
DECLARE
  signature text;
  function_oid oid;
  application_role text;
BEGIN
  FOREACH signature IN ARRAY ARRAY[
    'private.activity_require_actor(uuid,uuid,boolean)',
    'private.activity_validate_fields(jsonb,text[])',
    'private.activity_changes(jsonb,jsonb)',
    'private.activity_order_snapshot(text)',
    'private.activity_item_changes(jsonb,jsonb)',
    'private.activity_write(uuid,uuid,text,text,text,jsonb)',
    'public.audit_create_order(uuid,uuid,text,text,text,text,text,numeric,jsonb,text)',
    'public.audit_update_order(uuid,uuid,text,text,text,text,text,numeric,jsonb,text)',
    'public.audit_delete_order(uuid,uuid,text)',
    'public.audit_create_product(uuid,uuid,text,text,integer,integer,integer,numeric,boolean)',
    'public.audit_update_product(uuid,uuid,text,text,integer,integer,numeric,boolean)',
    'public.audit_delete_product(uuid,uuid,text)',
    'public.audit_adjust_stock(uuid,uuid,text,integer)',
    'public.audit_transition_order_separation(uuid,uuid,text,text)',
    'public.audit_update_own_name(uuid,uuid,text)',
    'public.audit_update_employee_status(uuid,uuid,uuid,text)'
  ]
  LOOP
    function_oid := to_regprocedure(signature);
    IF function_oid IS NULL THEN RAISE EXCEPTION 'Missing new function: %', signature; END IF;
    EXECUTE format('REVOKE ALL PRIVILEGES ON FUNCTION %s FROM PUBLIC, anon, authenticated, service_role', signature);
    IF signature LIKE 'public.audit_%' THEN
      EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', signature);
    END IF;
    FOREACH application_role IN ARRAY ARRAY['anon', 'authenticated', 'service_role']
    LOOP
      IF has_function_privilege(application_role, function_oid, 'EXECUTE')
         IS DISTINCT FROM (application_role = 'service_role' AND signature LIKE 'public.audit_%') THEN
        RAISE EXCEPTION 'Unexpected effective EXECUTE: role=%, function=%', application_role, signature;
      END IF;
    END LOOP;
  END LOOP;
END;
$permissions$;

-- REVIEW / INTEGRATION NOTES:
-- * Existing source creation accepts statuses other than cancelled; editing
--   accepts shipped/completed/cancelled and compensates cancelled stock.
--   These legacy behaviors remain unchanged, not silently replaced by a new
--   status policy. Status differences are included in order.updated details.
-- * Completed editing is blocked atomically in the new entry, matching the
--   current HTTP prohibition. Old entry points remain unchanged/access-controlled
--   as before. This file does not claim to close unaudited paths.
-- * Original create/update RETURNS void; product RETURNS SETOF products;
--   stock RETURNS integer; separation preserves its exact three-column shape.
-- * New direct-write replacements use 42501 (authorization), 22023 (validation),
--   P0002 (not found) and 23503 (linked product). Future Python integration must
--   map these to existing HTTP responses; no Python/JS is changed here.
-- * Original order editing replaces all items. Logs compare business values,
--   ignore item row IDs/order, and preserve duplicate multiplicities.
-- * Item diffs use {kind: added|removed, item: {product_id,product,quantity,
--   unit_price}}. They do not pretend to know stable line identity.
-- * No payload size cap, INSERT deduplication, auth events, new actor-session
--   claims, stock-reversal helper, collective workflow, or read RPC is added.
-- * Test actual FKs/triggers and cross-actor concurrency before approval.
--   Privileged direct item writes can bypass parent locking until a later stage.
-- * No SQL has been executed during preparation. Approval and integration tests
--   are required before deploying this file.

COMMIT;
